pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // admin of c is this test contract (deployer). Any other caller is not admin.
        vm.assume(actor != address(this));

        address ownerBefore = c.owner();

        vm.prank(actor);
        try c.setOwner(newOwner) {
            // Non-admin caller succeeded: owner must still be unchanged for the rule
            // "only the admin can ever change owner" to hold.
            assertTrue(c.owner() == ownerBefore && c.owner() != newOwner);
        } catch {
            // Reverted: fine, owner unchanged.
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

