pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address newOwner2) public {
        // Admin of c is the test contract (msg.sender at construction); owner starts == admin.
        // Keep the fuzzed actors distinct from the admin and from each other.
        vm.assume(newOwner != address(this));
        vm.assume(newOwner2 != newOwner);

        // Step 1: the admin legitimately sets the owner to a fuzzed address.
        vm.prank(address(this));
        c.setOwner(newOwner);
        assertEq(c.owner(), newOwner);

        // Step 2: the NEW owner (not the admin) tries to change ownership.
        // Rule: only the immutable admin may call setOwner, so this call must
        // revert and owner must remain newOwner forever.
        vm.prank(newOwner);
        try c.setOwner(newOwner2) {
            // call succeeded
        } catch {
            // call reverted
        }

        assertTrue(c.owner() == newOwner);
    }
}

